83	// ─────────────────────────────────────────────────────────────────────────
84	//  §3.1 — TMA-descriptor / operator reuse (shape-keyed host cache)
85	//
86	//  WHAT IS REUSED (and WHY this is the correct CUTLASS-3.6 reuse):
87	//  ----------------------------------------------------------------
88	//  CUTLASS 3.6 builds the Hopper TMA tensor-map descriptors *inside*
89	//  `op.initialize(args, ws, stream)` → `GemmKernel::to_underlying_arguments`
90	//  → `CollectiveMainloop::to_underlying_arguments`, which calls
91	//  `make_tma_copy_A/B_sm90(...)` (sm90_mma_tma_gmma_ss_warpspecialized.hpp
92	//  lines 215-226). Those descriptors (one cuTensorMapEncode each for A and B,
93	//  plus the epilogue's C map) are baked into the operator's `params_` member.
94	//  GemmUniversalAdapter exposes `run(stream)` precisely "to re-launch the same
95	//  kernel without updating internal params" (gemm_universal_adapter.h:545) —
96	//  i.e. reusing the already-built descriptors.
97	//
98	//  So the supported, internals-respecting reuse is NOT to reach into CUTLASS's
99	//  TMA path, but to CACHE THE INITIALIZED OPERATOR keyed by everything its
100	//  descriptors encode, and on a recurring shape skip
101	//  make_cute_packed_stride + Arguments construction + get_workspace_size +
102	//  initialize (which is where the cuTensorMapEncode calls live) and just call
103	//  the cached `op.run(stream)`.
104	//
105	//  DESCRIPTOR ADDRESS-STABILITY (correctness invariant):
106	//  ----------------------------------------------------------------
107	//  A Hopper TMA tensor map encodes the *global base address* of the tensor
108	//  (make_tma_copy is fed `make_tensor(ptr_A, ...)`), the box/shape and the
109	//  strides. Therefore a cached operator is bit-for-bit equivalent to a freshly
110	//  rebuilt one IFF (M,N,K), the A/B/C base pointers, AND the strides all match.
111	//  Strides here are a pure function of (M,N,K) (row-major packed), so the key
112	//  is {M,N,K, A, B, C}. The optimizer/model buffers this serves (param/m/v
113	//  state, weights, and the grown-once FP32 scratch) are allocated ONCE and keep
114	//  the same address every step → stable key → cache hit. If any buffer is
115	//  reallocated to a new address, the key changes → MISS → rebuild, so a stale
116	//  descriptor can never be launched against a moved buffer (that would be wrong
117	//  results / an illegal access). This is the load-bearing safety property.
118	//
119	//  WORKSPACE LIFETIME:
120	//  ----------------------------------------------------------------
121	//  For this builder (1x1x1 cluster, kGemm, no split-K) the kernel reports
122	//  get_workspace_size()==0 and the adapter adds a barrier workspace only when
123	//  cute::size(ClusterShape)>1 — so the served GEMMs need no workspace and
124	//  `initialize` is called with ws==nullptr. We still query the size and, if a
125	//  future tile/cluster change makes it non-zero, each cache entry OWNS its own
126	//  workspace allocation (freed on eviction) so a cached operator's params can
127	//  never dangle into the shared grow-only `sm90_get_workspace` buffer.
128	//
129	//  EVICTION: fixed-size, direct-mapped (hash → slot). On collision the resident
130	//  entry is evicted (its owned workspace freed) and replaced — bounded memory,
131	//  no leak. Only a handful of distinct (shape,ptr) signatures recur per run, so
132	//  collisions are rare.
133	//
134	//  THREAD-SAFETY: the cache is `thread_local` (one instance per template
135	//  instantiation PER HOST THREAD). The launcher is single-threaded per stream
136	//  in this codebase, so each launching thread owns its own cache and no lock is
137	//  needed — the former std::mutex has been dropped. A thread_local cache is also
138	//  strictly correct for multi-thread launchers: each thread caches only the
139	//  operators it itself built, so there is no cross-thread sharing to race on.
140	//  (The cached device buffers / TMA descriptors are stream/context state, not
141	//  thread state, but each thread re-builds+initializes its own operator on a
142	//  miss, so correctness holds; the only cost of thread-local is that two threads
143	//  launching the same shape each pay one build.)
144	//
145	//  ELECT/MBARRIER BOUNDARY (honest note):
146	//  ----------------------------------------------------------------
147	//  §3.4's elect_one_sync()/Mbarrier (warp_specialize.cuh) compose a
148	//  HAND-WRITTEN producer/consumer TMA staging loop. The CUTLASS GEMM is a
149	//  self-contained kernel that OWNS its TMA mainloop — there is no hand-written
150	//  TMA staging in mma.cuh to inject a leader/barrier into. Pairing the elect/
151	//  mbarrier primitives with TMA therefore belongs to the Stage-6 megakernel's
152	//  hand-written TMA path, NOT here. Stage 4.1 is the host-side operator/
153	//  descriptor cache only.
154	// ─────────────────────────────────────────────────────────────────────────
155	
156	// Problem signature the cached descriptors depend on. Pointers are part of the
157	// key because a TMA tensor map encodes the global base address (see above).
158	struct GemmCacheKey {
159	    int         M, N, K;
160	    const void* A;
161	    const void* B;
162	    void*       C;
163	
164	    bool operator==(const GemmCacheKey& o) const {
165	        return M == o.M && N == o.N && K == o.K &&
166	               A == o.A && B == o.B && C == o.C;
167	    }
168	};
169	
170	inline uint64_t sm90_gemm_key_hash(const GemmCacheKey& k) {
171	    // FNV-1a over the raw key bytes — cheap, decent spread for the small set
172	    // of distinct signatures that recur.
173	    auto mix = [](uint64_t h, uint64_t v) {
174	        h ^= v; h *= 0x100000001b3ull; return h;
175	    };
176	    uint64_t h = 0xcbf29ce484222325ull;
177	    h = mix(h, (uint64_t)(uint32_t)k.M);
178	    h = mix(h, (uint64_t)(uint32_t)k.N);
179	    h = mix(h, (uint64_t)(uint32_t)k.K);
180	    h = mix(h, (uint64_t)k.A);
181	    h = mix(h, (uint64_t)k.B);
182	    h = mix(h, (uint64_t)k.C);
183	    return h;
184	}
