307	// Typed-output variant of sm90_run_gemm_cached: identical operator cache and
308	// build/initialize/run logic, but the C operand is an ElementOut* buffer (the
309	// collective's ElementC == ElementOut), so the result lands directly in the
310	// activation dtype with NO FP32 scratch and NO separate cast kernel. Used by
311	// the §5/§7 templated-output collectives. The cache is keyed identically
312	// (the void* C in the key is the typed pointer reinterpret_cast to void*), and
313	// each (Gemm, ElementOut) instantiation owns its own slot table, so a typed-
314	// output operator is never confused with a float-output one.
315	template <typename Gemm, typename ElementA, typename ElementB,
316	          typename ElementAcc, typename ElementOut>
317	inline cudaError_t sm90_run_gemm_cached_out(
318	    int M, int N, int K,
319	    const void* A, const void* B, ElementOut* C,
320	    cudaStream_t stream)
321	{
322	    using StrideA = typename Gemm::GemmKernel::StrideA;
323	    using StrideB = typename Gemm::GemmKernel::StrideB;
324	    using StrideC = typename Gemm::GemmKernel::StrideC;
325	
326	    GemmCacheKey key{M, N, K, A, B, reinterpret_cast<void*>(C)};
327	    auto& cache = Sm90GemmCache<Gemm>::instance();
328	    int   slot  = sm90_gemm_slot<Gemm>(key);
329	    auto& e = cache.slots[slot];
330	
331	    if (e.valid && e.key == key) {
332	        cutlass::Status st = e.op.run(stream);
333	        return (st == cutlass::Status::kSuccess) ? cudaSuccess : cudaErrorUnknown;
334	    }
335	
336	    StrideA stride_a = cutlass::make_cute_packed_stride(StrideA{}, {M, K, 1});
337	    StrideB stride_b = cutlass::make_cute_packed_stride(StrideB{}, {N, K, 1});
338	    StrideC stride_c = cutlass::make_cute_packed_stride(StrideC{}, {M, N, 1});
339	
340	    typename Gemm::Arguments args{
341	        cutlass::gemm::GemmUniversalMode::kGemm,
342	        {M, N, K, 1},
343	        { reinterpret_cast<const ElementA*>(A), stride_a,
344	          reinterpret_cast<const ElementB*>(B), stride_b },
345	        { {ElementAcc(1.0f), ElementAcc(0.0f)},
346	          C, stride_c, C, stride_c }
347	    };
348	
349	    Gemm op;
350	    cutlass::Status st = op.can_implement(args);
351	    if (st != cutlass::Status::kSuccess) return cudaErrorNotSupported;
352	
353	    size_t ws_size = Gemm::get_workspace_size(args);
354	    if (e.valid && e.ws) { cudaFree(e.ws); e.ws = nullptr; e.ws_bytes = 0; }
355	
356	    void* ws = nullptr;
357	    if (ws_size > 0) {
358	        if (cudaMalloc(&ws, ws_size) != cudaSuccess) { e.valid = false; return cudaErrorMemoryAllocation; }
359	    }
360	    st = op.initialize(args, ws, stream);
361	    if (st != cutlass::Status::kSuccess) { if (ws) cudaFree(ws); e.valid = false; return cudaErrorUnknown; }
362	    st = op.run(stream);
363	    if (st != cutlass::Status::kSuccess) { if (ws) cudaFree(ws); e.valid = false; return cudaErrorUnknown; }
364	
365	    e.op = op; e.key = key; e.ws = ws; e.ws_bytes = ws_size; e.valid = true;
366	    return cudaSuccess;
367	}
