369	template <typename ElementInput>
370	struct Sm90Gemm {
371	    using ElementA   = ElementInput;
372	    using ElementB   = ElementInput;
373	    using ElementC   = float;          // FP32 output (matches cuBLAS path)
374	    using ElementAcc = float;          // FP32 accumulate
375	    using LayoutA    = cutlass::layout::RowMajor;
376	    using LayoutB    = cutlass::layout::RowMajor;
377	    using LayoutC    = cutlass::layout::RowMajor;
378	
379	    // 128-bit aligned access (16 bytes / sizeof(element)).
380	    static constexpr int AlignA = 128 / cutlass::sizeof_bits<ElementA>::value;
381	    static constexpr int AlignB = 128 / cutlass::sizeof_bits<ElementB>::value;
382	    static constexpr int AlignC = 128 / cutlass::sizeof_bits<ElementC>::value;
383	
384	    // §8 DOCUMENT-STOP — single 128x128x64 tile kept (no small-M variant):
385	    //   A small-M tile (e.g. 64x128x64) was considered to better fit the small
386	    //   M of several model GEMMs. It is NOT added because (a) the recurring
387	    //   operator cache (sm90_run_gemm_cached) is keyed per-Gemm-INSTANTIATION,
388	    //   so a second tile type would mean a second slot table + a runtime
389	    //   M-threshold dispatch and a SECOND full kernel build per element type —
390	    //   roughly doubling these already-heavy CUTLASS TUs' nvcc time/memory
391	    //   (the build is near the documented OOM ceiling: heavy TUs must compile
392	    //   serially), and (b) KernelScheduleAuto already picks a sensible
393	    //   warp-specialized schedule for this tile across the M range in use, and
394	    //   correctness is identical regardless of tile (FP32 accumulate). The
395	    //   single proven 128x128x64 tile is therefore retained; revisit only with
396	    //   measured per-shape occupancy data (no GPU here).
397	    using TileShape    = cute::Shape<cute::_128, cute::_128, cute::_64>;
398	    using ClusterShape = cute::Shape<cute::_1, cute::_1, cute::_1>;
399	
400	    // Collective epilogue: linear combination (alpha/beta), FP32 accumulate.
401	    using CollectiveEpilogue =
402	        typename cutlass::epilogue::collective::CollectiveBuilder<
403	            cutlass::arch::Sm90, cutlass::arch::OpClassTensorOp,
404	            TileShape, ClusterShape,
405	            cutlass::epilogue::collective::EpilogueTileAuto,
406	            ElementAcc, ElementAcc,
407	            ElementC, LayoutC, AlignC,
408	            ElementC, LayoutC, AlignC,
409	            cutlass::epilogue::collective::EpilogueScheduleAuto
410	        >::CollectiveOp;
411	
412	    // Collective mainloop: Sm90 TMA + WGMMA, auto stage count / schedule.
413	    //
414	    // §7 DOCUMENT-STOP — KernelScheduleAuto kept (no KernelTmaWarpSpecialized-
415	    //   Cooperative large-M path). The Cooperative schedule was attempted; it
416	    //   composes correctly in isolation BUT delivering it as a large-M variant
417	    //   requires: (1) a matching cooperative EPILOGUE schedule (TmaWarp-
418	    //   SpecializedCooperative, not EpilogueScheduleAuto), (2) a 2-warpgroup-
419	    //   friendly tile (the cooperative kernel splits the M tile across two
420	    //   warpgroups — the proven 128x128x64 / 1x1x1 config is not its intended
421	    //   shape), and (3) a SECOND full kernel instantiation per element type
422	    //   behind a runtime M-threshold dispatch. That doubles the build cost on
423	    //   TUs already compiled serially to dodge nvcc OOM, for an UNMEASURED
424	    //   (no-GPU) win. KernelScheduleAuto already selects a warp-specialized
425	    //   Hopper schedule and is correct (FP32 accumulate) across the M range.
426	    //   Kept as the single, proven path; revisit with measured large-M data.
427	    using CollectiveMainloop =
428	        typename cutlass::gemm::collective::CollectiveBuilder<
429	            cutlass::arch::Sm90, cutlass::arch::OpClassTensorOp,
430	            ElementA, LayoutA, AlignA,
431	            ElementB, LayoutB, AlignB,
432	            ElementAcc,
433	            TileShape, ClusterShape,
434	            cutlass::gemm::collective::StageCountAutoCarveout<
435	                static_cast<int>(sizeof(typename CollectiveEpilogue::SharedStorage))>,
436	            cutlass::gemm::collective::KernelScheduleAuto
437	        >::CollectiveOp;
438	
439	    using GemmKernel = cutlass::gemm::kernel::GemmUniversal<
440	        cute::Shape<int, int, int, int>,   // (M, N, K, L) problem shape
441	        CollectiveMainloop,
442	        CollectiveEpilogue>;
443	
444	    using Gemm = cutlass::gemm::device::GemmUniversalAdapter<GemmKernel>;
445	};
