447	// Run a single row-major C = A*B with FP32 accumulate on the Sm90 collective.
448	template <typename ElementInput>
449	inline cudaError_t sm90_run_gemm(
450	    int M, int N, int K,
451	    const void* A, const void* B, float* C,
452	    cudaStream_t stream)
453	{
454	    using G          = Sm90Gemm<ElementInput>;
455	    using Gemm       = typename G::Gemm;
456	    using ElementA   = typename G::ElementA;
457	    using ElementB   = typename G::ElementB;
458	    using ElementAcc = typename G::ElementAcc;
459	
460	    // §3.1: serve from the shape-keyed operator cache. A recurring
461	    // (M,N,K, A,B,C) signature reuses the already-built TMA descriptors and
462	    // skips make_stride + Arguments + initialize (the cuTensorMapEncode path);
463	    // a miss builds + initializes + installs. Numerically identical to the
464	    // rebuild-every-time path (same args → same params_).
465	    return sm90_run_gemm_cached<Gemm, ElementA, ElementB, ElementAcc>(
466	        M, N, K, A, B, C, stream);
467	}
